function Assert-Exact([string]$Name,$Actual,$Expected) { if($Actual -cne $Expected) { throw "Angel Tin dossier $Name differs: expected '$Expected', actual '$Actual'." } }
function Assert-Props([string]$Name,$Object,[string[]]$Expected) {
  if($null -eq $Object) { throw "Angel Tin dossier $Name is absent." }
  $actual=@($Object.PSObject.Properties.Name|Sort-Object);$wanted=@($Expected|Sort-Object)
  if($actual.Count -ne $wanted.Count -or (@(Compare-Object -CaseSensitive $actual $wanted)).Count -ne 0) { throw "Angel Tin dossier $Name properties differ." }
}
function Assert-Array([string]$Name,$Actual,[string[]]$Expected) {
  $actual=@($Actual|ForEach-Object {[string]$_});if($actual.Count -ne $Expected.Count -or (@(Compare-Object -CaseSensitive $actual $Expected)).Count -ne 0) { throw "Angel Tin dossier $Name differs." }
}
