gory $record.conditional_crafting_category_capability.category 'implicit-crafting';Assert-Array conditional_crafting_category_capability.entities $record.conditional_crafting_category_capability.entities @('assembling-machine-1','assembling-machine-2','assembling-machine-3');Assert-Exact conditional_crafting_category_capability.not_a_reachable_route $record.conditional_crafting_category_capability.not_a_reachable_route $true
Assert-Props productivity $record.productivity @('permission_recipes','native_owner_technologies','mir_owner_technology','disposition');Assert-Array productivity.permission_recipes $record.productivity.permission_recipes @('angels-plate-tin','angels-plate-tin-2');Assert-Array productivity.native_owner_technologies $record.productivity.native_owner_technologies @();if($null -ne $record.productivity.mir_owner_technology) {throw 'Angel Tin dossier MIR owner must be null.'};Assert-Exact productivity.disposition $record.productivity.disposition 'permission-present-without-native-or-mir-owner'
