$engineRoot=Split-Path (Split-Path (Split-Path $engine -Parent)-Parent)-Parent;[IO.File]::WriteAllText((Join-Path $run 'config.ini'),"[path]`nread-data=$($engineRoot.Replace('\','/'))/data`nwrite-data=$($run.Replace('\','/'))/userdata`n",[Text.UTF8Encoding]::new($false))
$start=[Diagnostics.ProcessStartInfo]::new($engine);$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;foreach($argument in @('--config',(Join-Path $run 'config.ini'),'--mod-directory',$mods,'--create',(Join-Path $run 'audit.zip'))){$start.ArgumentList.Add($argument)};$process=[Diagnostics.Process]::Start($start);try{$stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync();if(-not $process.WaitForExit(120000)){$process.Kill($true);throw "Angel Tin audit timed out $run"};$text=$stdout.GetAwaiter().GetResult()+$stderr.GetAwaiter().GetResult();[IO.File]::WriteAllText((Join-Path $run 'engine.log'),$text,[Text.UTF8Encoding]::new($false));if($process.ExitCode -ne 0){throw "Angel Tin audit engine failed: $run`n$($text.Substring([Math]::Max(0,$text.Length-2500)))"}}finally{$process.Dispose()}
$log=Join-Path $run 'userdata/factorio-current.log';if(-not(Test-Path -LiteralPath $log -PathType Leaf)){throw 'Angel Tin audit Factorio log is absent.'};$logText=Get-Content -Raw -LiteralPath $log;if($logText -notmatch [regex]::Escape('[mir-angel-tin-audit] DATA PASS final=angels-plate-tin ordinary-acquisition=0 productivity-owner=none frontier-reachable=false')){throw 'Angel Tin audit data assertion is absent.'};if($logText -notmatch [regex]::Escape('[mir-angel-tin-audit] RUNTIME PASS diagnostic-only-no-owner')){throw 'Angel Tin audit runtime assertion is absent.'}
